import json,hashlib,copy
from pathlib import Path
ROOT=Path(__file__).resolve().parent
P=json.loads((ROOT/'packet.json').read_text()); E={e['source_id']:e for e in P['entries']}; T={s:e['text'] for s,e in E.items()}; F=P['selection_design']['focal_source_ids']
A={'schema_version':'0.3','run_id':'R12_A','episode_id':'CoreKnots_R12_shared','packet_sha256':hashlib.sha256((ROOT/'packet.json').read_bytes()).hexdigest(),'entry_screening':[],'units':[],'relations':[],'episode_summary':{'observed_outcomes':[],'mechanisms':[],'missing_evidence':[],'unresolved_questions':[]}}
U={}; notes={}; sequences=[]
def ev(s,q=None,start=None):
 t=T[s]; q=t if q is None else q
 if start is None:start=t.index(q)
 assert t[start:start+len(q)]==q,(s,q)
 return {'source_id':s,'span':{'start':start,'end':start+len(q),'quote':q}}
def unit(id,s,q=None,role='statement',grammar='regulative',speech='proposed',scope='case_specific',parse='literal',force='recommendation',itype='undetermined',standing='text_only',rationale='',level='operational',observed='operational',alt='',unc='',confidence='plausible',quotation='none',markup='plain',parent=None,levels=None,flags=None):
 x={'unit_id':id,'source_id':s,'span':ev(s,q)['span'],'parent_unit_id':parent,'grammar':grammar,'speech_act':speech,'scope':scope,'components':[],'institution':{'type':itype,'standing':standing,'dispute_present':False,'rationale':rationale or 'A contribution-specific proposal is expressed; the packet does not establish a recurring obligation or authorization for this particular edit.','evidence':[ev(s,q)],'recognition':[],'authority_evidence':[]},'statement_target_level':level,'observed_action_level':observed,'level_rationale':'The focal activity is contribution, review, or maintenance within the repository; the observed act is discussion in that process.','complexity_flags':flags or ['none'],'alternative_interpretation':alt,'confidence':confidence,'uncertainty_reason':unc,'record_role':role,'parse_mode':parse,'deontic_force':force,'level_alternatives':levels or [],'presentation':{'quotation':quotation,'markup':markup,'rationale':'Coding describes the supplied occurrence; no unobserved edit history is inferred.'},'disposition_events':[]}
 if role!='statement':
  x.update(grammar='not_institutional',statement_target_level='not_applicable',deontic_force='nondeontic',parse_mode='literal')
  x['institution'].update(type='not_applicable',standing='not_applicable',rationale=rationale or 'This record preserves a communicative act or repeated occurrence, not an additional independent institutional proposition.')
 if role=='container':x.update(observed_action_level='not_applicable',speech_act='other')
 A['units'].append(x);U[id]=x;return x

def comp(id,symbol,text,q=None,s=None,basis='explicit',role='local',note=''):
 u=U[id];s=s or u['source_id'];q=q or text
 start=None
 if s==u['source_id']:
  loc=T[s].find(q,u['span']['start'],u['span']['end'])
  if loc>=0:start=loc
 e=ev(s,q,start)
 c={'symbol':symbol,'text':text,'basis':basis,'evidence':[e],'inference_note':note,'occurrence_role':role}
 u['components'].append(c);return c

def inf(id,symbol,text,q,s=None,note='',role='semantic_inference',basis='context_inferred'):
 return comp(id,symbol,text,q,s,basis,role,note or 'This argument/action is reconstructed from the anchored utterance in its contribution-review context; the role is not directly asserted in this parse.')
def event(id,kind,s,q,target='this_proposition',basis='explicit',rationale='',disp=False,extra=None):
 d={'kind':kind,'target':target,'basis':basis,'evidence':[ev(s,q)]+(extra or []),'rationale':rationale}
 U[id]['disposition_events' if disp else 'institution'].append(d) if disp else U[id]['institution']['recognition'].append(d)
 return d

def rel(a,b,typ,s,q,basis='explicit',rationale='',scope='not_applicable',extra=None):
 A['relations'].append({'from_unit_id':a,'to_unit_id':b,'type':typ,'basis':basis,'rationale':rationale,'evidence':[ev(s,q)]+(extra or []),'logic_scope':scope})
def ctx(id,s,q=None,speech='reported_action',**kw):return unit(id,s,q,role='context',speech=speech,**kw)
def quote(id,s,q,original):
 unit(id,s,q,role='quotation',speech='asserted',quotation='repeated')
 rel(id,original,'quotes',s,q,rationale='This is a repeated occurrence of the linked supplied original, not independent endorsement.',extra=[ev(U[original]['source_id'],U[original]['span']['quote'])])
def doc(id,s,q):
 U[id]['institution']['evidence'].append(ev(s,q));U[id]['institution']['authority_evidence'].append(ev(s,q))
def outcome(claim,*evidence):A['episode_summary']['observed_outcomes'].append({'claim':claim,'evidence':list(evidence)})
def mech(category,claim,ids,evidence,alt,status='supported_sequence'):
 d={'category':category,'claim':claim,'unit_ids':ids,'evidence':evidence,'alternative_explanation':alt,'status':status};A['episode_summary']['mechanisms'].append(d);sequences.append(d)
def note(s,reason,missing='',alternative=''):
 notes[s]={'source_id':s,'reasoning':reason,'missing_context':missing,'consequential_alternative_interpretations':alternative}
def close(id,pr,merged=False,specific=False,extra=None):
 m='M'+str(pr);q='"merged": '+('true' if merged else 'false')
 event(id,'recorded_merged' if merged else 'recorded_closed_unmerged',m,q,target='this_proposition' if specific else 'broader_proposal',rationale=('Supplied patch and metadata establish the particular change in the merged contribution.' if specific else 'Metadata establishes the broader contribution status, not adoption or rejection of every embedded expectation.'),disp=True,extra=extra)

